package com.auraboot.framework.file.support;

import org.springframework.web.multipart.MultipartFile;

import java.io.ByteArrayInputStream;
import java.io.File;
import java.io.IOException;
import java.io.InputStream;
import java.nio.file.Files;

/** Host-owned immutable generated bytes passed to the ordinary upload content validators. */
public final class GeneratedArtifactMultipartFile implements MultipartFile {
    private final String filename;
    private final String contentType;
    private final byte[] bytes;

    public GeneratedArtifactMultipartFile(String filename, String contentType, byte[] bytes) {
        this.filename = FileNameEncodingSupport.normalizeOriginalFilename(filename);
        this.contentType = contentType;
        this.bytes = bytes.clone();
    }

    @Override public String getName() { return "file"; }
    @Override public String getOriginalFilename() { return filename; }
    @Override public String getContentType() { return contentType; }
    @Override public boolean isEmpty() { return bytes.length == 0; }
    @Override public long getSize() { return bytes.length; }
    @Override public byte[] getBytes() { return bytes.clone(); }
    @Override public InputStream getInputStream() { return new ByteArrayInputStream(bytes); }
    @Override public void transferTo(File destination) throws IOException { Files.write(destination.toPath(), bytes); }
}
